  function renderPendingEvent(){const pending=state.policies?.pendingEvent;if(!pending)return false;const city=state.data.cities.find(c=>c.id===pending.targetCityId);$("eventKind").textContent=pending.type==="historical"?"历史事件":"地方事件";$("eventTitle").textContent=pending.name;$("eventText").textContent=pending.text;$("eventLocation").textContent=city?`事发地点 · ${city.name} · ${city.province}`:`天下大势 · 第 ${pending.turn} 旬`;$('eventChoices').innerHTML=pending.choices.map(choice=>`<button class="event-choice" data-event-choice="${esc(choice.id)}"><b>${esc(choice.label)}</b><span>${esc(choice.description||"作出决断")}</span></button>`).join("");$("eventChoices").querySelectorAll("[data-event-choice]").forEach(button=>button.onclick=()=>{const before=state.economicSnapshot(),result=state.engine.resolveEventChoice(state,button.dataset.eventChoice),after=state.economicSnapshot();if(!result)return;if(state.reports[0]){state.reports[0].events.push(result);state.reports[0].summary=`完成 ${state.reports[0].events.length} 项阶段结算。`;state.reports[0].resourceDelta??={};for(const key of Object.keys(before))state.reports[0].resourceDelta[key]=(state.reports[0].resourceDelta[key]||0)+after[key]-before[key]}$("eventDialog").close();renderResources();renderSelection();renderReports();renderForces();map.draw();log(result.text,"sys");toast("事件决策已执行");if(pendingTurnBriefing){pendingTurnBriefing=buildTurnBriefing(state.reports[0],pendingTurnBriefing.context);showTurnBriefing()}});if(!$("eventDialog").open)$("eventDialog").showModal();return true}
